package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Consent based groups; foreground polling never changes the selected conversation. */
final class GroupsView extends LinearLayout {
 private JSONObject unreadCounts=new JSONObject();private String readThrough="";
 void unread(JSONObject counts){unreadCounts=counts==null?new JSONObject():counts;if(selected==null&&!busy)loadGroups();}
 private boolean realtimeReady,liveDirty;private final Runnable liveDrain=()->drainLive();
 void realtimeConnection(boolean ready){realtimeReady=ready;schedule();}
 void realtimeEvent(String table,String type,String id){if(!active||!isAttachedToWindow()||(!table.isEmpty()&&!table.startsWith("clt_chat_group_")))return;if(table.equals("clt_chat_group_messages")&&type.equals("DELETE")&&!id.isEmpty()&&selected!=null){JSONArray next=new JSONArray();for(int i=0;i<messages.length();i++){JSONObject row=messages.optJSONObject(i);if(!id.equals(row.optString("id")))next.put(row);}if(next.length()!=messages.length()){int y=scroll.getScrollY();messages=next;renderMessages();scroll.scrollTo(0,y);}}if(selected!=null&&!id.isEmpty()&&(table.equals("clt_chat_group_reactions")||type.equals("UPDATE"))){boolean known=false;for(int i=50;i<messages.length();i++)known|=id.equals(messages.optJSONObject(i).optString("id"));if(known){String group=selected.optString("id");int ticket=epoch;repo.groupMessageCurrent(group,id,(rows,error)->{if(error!=null||ticket!=epoch||!active||selected==null||!group.equals(selected.optString("id")))return;JSONArray next=new JSONArray();for(int i=0;i<messages.length();i++){JSONObject old=messages.optJSONObject(i);if(!id.equals(old.optString("id")))next.put(old);else if(rows.length()>0)next.put(rows.optJSONObject(0));}int y=scroll.getScrollY();messages=next;renderMessages();scroll.post(()->scroll.scrollTo(0,y));});}}liveDirty=true;timer.removeCallbacks(liveDrain);timer.postDelayed(liveDrain,120);}
 private void drainLive(){if(!active||!isAttachedToWindow()){liveDirty=false;return;}if(busy||sending||polling){timer.postDelayed(liveDrain,250);return;}liveDirty=false;if(selected!=null)loadMessages(false,false);else loadGroups();}
 private final AccountRepository repo;private final LinearLayout list,header,composer;private final ScrollView scroll;private final TextView state;private final EditText draft;private JSONObject selected;private JSONArray messages=new JSONArray();private boolean active,busy,sending,polling;private int epoch;private final android.os.Handler timer=new android.os.Handler(android.os.Looper.getMainLooper());private final Runnable tick=()->loadMessages(false,false);
 GroupsView(Context c){super(c);repo=new AccountRepository(c);setOrientation(VERTICAL);setPadding(dp(16),dp(6),dp(16),dp(8));header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);addView(header);state=text("",11,0xffaa9ebc);addView(state);scroll=new ScrollView(c);scroll.setVerticalScrollBarEnabled(false);list=new LinearLayout(c);list.setOrientation(VERTICAL);scroll.addView(list);addView(scroll,new LayoutParams(-1,0,1));composer=new LinearLayout(c);composer.setGravity(Gravity.CENTER_VERTICAL);draft=NativeSheet.input(c,"Mensagem ao grupo",4000);draft.setMaxLines(4);composer.addView(draft,new LayoutParams(0,-2,1));Button stickers=button("",false);AppStyle.icon(stickers,ActionIcon.STICKER,0xffffce7d);stickers.setContentDescription("Enviar figurinha");composer.addView(stickers,new LayoutParams(dp(48),dp(48)));stickers.setOnClickListener(v->{if(selected==null||sending)return;String id=selected.optString("id");StickerSheet.show(c,x->{if(selected==null||!id.equals(selected.optString("id"))||sending)return;sending=true;repo.groupSticker(id,x.optString("id"),(r,e)->{sending=false;if(e!=null){state.setText(e);return;}loadMessages(true,true);});});});Button send=button("",true);send.setContentDescription("Enviar mensagem");AppStyle.icon(send,ActionIcon.SEND,0xffffffff);composer.addView(send,new LayoutParams(dp(48),dp(48)));send.setOnClickListener(v->send());addView(composer);renderHeader();loadGroups();}
 void setForeground(boolean value){active=value;if(!value){timer.removeCallbacks(liveDrain);liveDirty=false;}epoch++;polling=false;timer.removeCallbacks(tick);if(value&&selected!=null)schedule();else if(value)loadGroups();}
 @Override protected void onDetachedFromWindow(){setForeground(false);super.onDetachedFromWindow();}
 private void schedule(){timer.removeCallbacks(tick);if(active&&isAttachedToWindow()&&selected!=null)timer.postDelayed(tick,realtimeReady?45000:8000);}
 boolean back(){if(selected==null)return false;if(sending){state.setText("Aguarde a confirmação do envio.");return true;}epoch++;polling=false;selected=null;messages=new JSONArray();draft.setText("");timer.removeCallbacks(tick);renderHeader();loadGroups();return true;}
 private void renderHeader(){header.removeAllViews();composer.setVisibility(selected==null?GONE:VISIBLE);if(selected==null){TextView title=text("Seus grupos",17,0xfff3efff);header.addView(title,new LayoutParams(0,dp(44),1));Button create=button("+ Criar",true);header.addView(create,new LayoutParams(dp(96),dp(44)));create.setOnClickListener(v->create());Button refresh=button("↻",false);refresh.setContentDescription("Atualizar grupos");header.addView(refresh,new LayoutParams(dp(44),dp(44)));refresh.setOnClickListener(v->loadGroups());}else{Button back=button("‹",false);header.addView(back,new LayoutParams(dp(40),dp(44)));back.setOnClickListener(v->back());ImageView photo=avatar(selected.optString("foto_path"),true);header.addView(photo,new LayoutParams(dp(34),dp(34)));TextView title=text(selected.optString("nome"),16,0xfff4efff);title.setPadding(dp(8),0,0,0);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(title,new LayoutParams(0,dp(44),1));Button settings=button("⚙",false);settings.setContentDescription("Configurações do grupo");header.addView(settings,new LayoutParams(dp(44),dp(44)));settings.setOnClickListener(v->settings());}}
 void openNotification(String id){state.setText("Abrindo grupo…");repo.groups((rows,error)->{if(!isAttachedToWindow())return;if(error!=null){state.setText(error);return;}for(int i=0;i<rows.length();i++){JSONObject g=rows.optJSONObject(i);if(g!=null&&id.equals(g.optString("id"))){epoch++;polling=false;readThrough="";selected=g;messages=new JSONArray();renderHeader();loadMessages(true,true);return;}}state.setText("Este grupo foi removido ou você não participa mais dele.");});}
 private void loadGroups(){if(busy||selected!=null)return;busy=true;state.setText("Carregando grupos…");int ticket=epoch;repo.groups((rows,error)->{busy=false;if(selected!=null)return;list.removeAllViews();if(error!=null){state.setText(error);return;}state.setText(rows.length()+" grupos • entrada por convite");for(int i=0;i<rows.length();i++){JSONObject g=rows.optJSONObject(i);LinearLayout row=row();row.addView(avatar(g.optString("foto_path"),true),new LayoutParams(dp(42),dp(42)));LinearLayout info=new LinearLayout(getContext());info.setOrientation(VERTICAL);info.setPadding(dp(10),0,dp(8),0);info.addView(text(g.optString("nome"),15,0xfff4efff));info.addView(text(g.optBoolean("_admin")?"Administrador":"Participante",11,0xffb9a3de));row.addView(info,new LayoutParams(0,-2,1));int n=unreadCounts.optInt(g.optString("id"));if(n>0)row.addView(text(n>99?"99+":String.valueOf(n),12,0xffff96bf));row.addView(text("›",24,0xffc4b3ff));list.addView(row);row.setOnClickListener(v->{epoch++;polling=false;readThrough="";selected=g;messages=new JSONArray();renderHeader();loadMessages(true,true);});}if(rows.length()==0)list.addView(text("Crie um grupo para conversar com seus amigos.",13,0xffaaa0b8));repo.groupInvites((invites,e)->{if(selected!=null)return;if(e!=null){state.setText("Grupos carregados • convites: "+e);return;}for(int k=0;k<invites.length();k++){JSONObject invite=invites.optJSONObject(k);LinearLayout box=panel();box.addView(text("📨 Convite • "+invite.optString("nome","Grupo"),15,0xffe3d2ff));LinearLayout actions=new LinearLayout(getContext());box.addView(actions);for(boolean accept:new boolean[]{true,false}){Button b=button(accept?"Aceitar":"Recusar",accept);actions.addView(b,new LayoutParams(0,dp(44),1));b.setOnClickListener(v->{b.setEnabled(false);repo.groupRespond(invite.optString("id"),accept,(r,f)->{if(f!=null){b.setEnabled(true);state.setText(f);return;}loadGroups();});});}list.addView(box,0);}});});}
 private void loadMessages(boolean explicit,boolean bottom){if(selected==null||polling||sending){schedule();return;}if(!explicit&&!active)return;String id=selected.optString("id");int ticket=epoch;polling=true;repo.groupMessages(id,0,(rows,error)->{if(ticket!=epoch||selected==null||!id.equals(selected.optString("id")))return;polling=false;if(error!=null){state.setText(error);schedule();return;}JSONArray merged=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject m=rows.optJSONObject(i);merged.put(m);seen.add(m.optString("id"));}if(rows.length()==50){String boundary=rows.optJSONObject(49).optString("created_at");for(int i=0;i<messages.length();i++){JSONObject m=messages.optJSONObject(i);if(m.optString("created_at").compareTo(boundary)<=0&&seen.add(m.optString("id")))merged.put(m);}}int y=scroll.getScrollY();boolean atBottom=list.getHeight()-scroll.getHeight()-y<dp(64);if(!merged.toString().equals(messages.toString())||explicit){messages=merged;renderMessages();scroll.post(()->{if(ticket!=epoch)return;if(bottom||atBottom)scroll.fullScroll(FOCUS_DOWN);else scroll.scrollTo(0,y);});}if(active&&rows.length()>0){String through=rows.optJSONObject(0).optString("created_at");if(UnreadPolicy.advance(MessageTime.epoch(through),MessageTime.epoch(readThrough),active))repo.groupRead(id,through,(r,e)->{if(e==null){if(selected!=null&&id.equals(selected.optString("id")))readThrough=through;if(getContext() instanceof MainActivity)((MainActivity)getContext()).refreshChatCounts();}});}state.setText(messages.length()==0?"Nenhuma mensagem ainda.":"Conversa em grupo • segure uma mensagem para ver opções");schedule();});}
 private void older(){if(selected==null||polling)return;polling=true;String id=selected.optString("id");int ticket=epoch;int oldHeight=list.getHeight(),y=scroll.getScrollY();repo.groupMessages(id,messages.length(),(rows,e)->{if(ticket!=epoch)return;polling=false;if(e!=null){state.setText(e);return;}Set<String> ids=new HashSet<>();for(int i=0;i<messages.length();i++)ids.add(messages.optJSONObject(i).optString("id"));for(int i=0;i<rows.length();i++)if(ids.add(rows.optJSONObject(i).optString("id")))messages.put(rows.optJSONObject(i));renderMessages();if(rows.length()<50&&list.getChildCount()>0)list.getChildAt(0).setVisibility(GONE);scroll.post(()->scroll.scrollTo(0,y+list.getHeight()-oldHeight));schedule();});}
 private void renderMessages(){list.removeAllViews();if(messages.length()>=50){Button older=button("Mensagens anteriores",false);list.addView(older);older.setOnClickListener(v->older());}String user=me();for(int i=messages.length()-1;i>=0;i--){JSONObject m=messages.optJSONObject(i);boolean mine=user.equals(m.optString("remetente_id"));LinearLayout envelope=new LinearLayout(getContext());envelope.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);LayoutParams ep=new LayoutParams(-1,-2);ep.setMargins(mine?dp(36):0,dp(3),mine?0:dp(36),dp(3));list.addView(envelope,ep);LinearLayout bubble=panel();bubble.setPadding(dp(10),dp(6),dp(10),dp(6));bubble.setBackground(AppStyle.shape(bubble,mine?0xff51318b:0xff252032,15));envelope.addView(bubble,new LayoutParams(-2,-2));JSONObject author=m.optJSONObject("_author");if(!mine)bubble.addView(text(author==null?"Participante":author.optString("nome"),11,0xffcbb2ff));String content=m.isNull("texto")?"":m.optString("texto");if(!content.isEmpty()){TextView body=text(content,14,0xfff4efff);body.setMaxWidth(dp(Math.max(100,Math.min(280,getResources().getConfiguration().screenWidthDp-92))));bubble.addView(body);}String path=m.optString("midia_path","");if(path.matches("[a-zA-Z0-9-]+/[a-zA-Z0-9._-]+\\.(jpg|jpeg|png|webp)")){ImageView image=new ImageView(getContext());image.setScaleType(ImageView.ScaleType.FIT_CENTER);bubble.addView(image,new LayoutParams(dp(150),dp(150)));AccountImageLoader.load(image,BuildConfig.SUPABASE_URL+"/storage/v1/object/public/group-chat-media/"+path);}bubble.addView(text(MessageTime.time(m.optString("created_at")),9,0xffc1b1d7));JSONArray reactions=m.optJSONArray("_reactions");String badges="";if(reactions!=null)for(String emoji:new String[]{"❤️","😂","🔥","👍"}){int count=0;for(int j=0;j<reactions.length();j++)if(emoji.equals(reactions.optJSONObject(j).optString("emoji")))count++;if(count>0)badges+=emoji+" "+count+"  ";}if(!badges.isEmpty())bubble.addView(text(badges,11,0xffedddff));press(bubble,m);}}
 private void press(View view,JSONObject message){view.setOnLongClickListener(v->{if(selected==null)return true;String group=selected.optString("id");NativeSheet menu=new NativeSheet(getContext(),"Mensagem");Button reply=button("Responder",false);AppStyle.icon(reply,ActionIcon.REPLY,0xffbda7ff);menu.body.addView(reply);reply.setOnClickListener(w->{String text=message.isNull("texto")?"Figurinha":message.optString("texto");draft.setText("> "+text.replace('\n',' ').substring(0,Math.min(180,text.replace('\n',' ').length()))+"\n");draft.requestFocus();menu.dialog.dismiss();});for(String emoji:new String[]{"❤️","😂","🔥","👍"}){boolean exists=false;JSONArray reactions=message.optJSONArray("_reactions");if(reactions!=null)for(int i=0;i<reactions.length();i++){JSONObject r=reactions.optJSONObject(i);if(me().equals(r.optString("user_id"))&&emoji.equals(r.optString("emoji")))exists=true;}boolean add=!exists;Button reaction=button(emoji+(add?" Reagir":" Remover reação"),false);menu.body.addView(reaction);reaction.setOnClickListener(w->{reaction.setEnabled(false);repo.groupReaction(group,message.optString("id"),emoji,add,(r,e)->{if(e!=null){reaction.setEnabled(true);Toast.makeText(getContext(),e,Toast.LENGTH_LONG).show();return;}menu.dialog.dismiss();loadMessages(true,false);});});}if(me().equals(message.optString("remetente_id"))){Button delete=button("Apagar mensagem",false);menu.body.addView(delete);delete.setOnClickListener(w->confirm("Apagar esta mensagem?",()->repo.groupDeleteMessage(group,message.optString("id"),(r,e)->{if(e!=null){Toast.makeText(getContext(),e,Toast.LENGTH_LONG).show();return;}menu.dialog.dismiss();loadMessages(true,false);})));}menu.show();return true;});if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)press(group.getChildAt(i),message);}}
 private void send(){if(selected==null||sending)return;String text=draft.getText().toString();try{GroupInput.message(text);}catch(IllegalArgumentException e){state.setText(e.getMessage());return;}sending=true;String id=selected.optString("id");draft.setEnabled(false);repo.groupSend(id,text,(r,e)->{sending=false;draft.setEnabled(true);if(e!=null){state.setText(e);return;}draft.setText("");loadMessages(true,true);});}
 private void create(){NativeSheet sheet=new NativeSheet(getContext(),"Novo grupo");EditText name=NativeSheet.input(getContext(),"Nome do grupo",60);sheet.body.addView(name);sheet.body.addView(text("Os amigos selecionados receberão um convite.",12,0xffbfb0d0));LinearLayout people=new LinearLayout(getContext());people.setOrientation(VERTICAL);sheet.body.addView(people);TextView status=text("Carregando amigos…",12,0xffc1a6ff);sheet.body.addView(status);Set<String> chosen=new LinkedHashSet<>();loadFriends(people,chosen,null,status,0);Button create=button("Criar e enviar convites",true);sheet.footer.setVisibility(VISIBLE);sheet.footer.addView(create);create.setOnClickListener(v->{create.setEnabled(false);sheet.busy(true);repo.groupCreate(name.getText().toString(),new JSONArray(chosen),(r,e)->{sheet.busy(false);create.setEnabled(true);if(e!=null){status.setText(e);return;}sheet.dialog.dismiss();loadGroups();});});sheet.show();}
 private void loadFriends(LinearLayout people,Set<String> chosen,Set<String> excluded,TextView state,int offset){repo.friends(offset,(rows,e)->{if(e!=null){state.setText(e);return;}state.setText("");for(int i=0;i<rows.length();i++){JSONObject friend=rows.optJSONObject(i);String id=friend.optString("id");if(friend.optBoolean("unavailable")||(excluded!=null&&excluded.contains(id)))continue;CheckBox check=new CheckBox(getContext());check.setText(friend.optString("nome"));check.setTextColor(0xffeee2ff);check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffad83f2));LinearLayout person=row();person.addView(avatar(friend.optString("avatar_url"),false),new LayoutParams(dp(32),dp(32)));person.addView(check,new LayoutParams(0,-2,1));people.addView(person);check.setOnCheckedChangeListener((b,yes)->{if(yes)chosen.add(id);else chosen.remove(id);});}if(rows.length()==50){Button more=button("Mais amigos",false);people.addView(more);more.setOnClickListener(v->{people.removeView(more);loadFriends(people,chosen,excluded,state,offset+50);});}});}
 private void settings(){if(selected==null)return;JSONObject group=selected;String id=group.optString("id");boolean admin=group.optBoolean("_admin");NativeSheet sheet=new NativeSheet(getContext(),"Configurações do grupo");LinearLayout details=new LinearLayout(getContext()),participants=new LinearLayout(getContext()),invites=new LinearLayout(getContext());LinearLayout[] panes={details,participants,invites};for(LinearLayout pane:panes){pane.setOrientation(VERTICAL);sheet.body.addView(pane);}participants.setVisibility(GONE);invites.setVisibility(GONE);sheet.controls.setVisibility(VISIBLE);LinearLayout tabs=new LinearLayout(getContext());sheet.controls.addView(tabs);String[] labels={"Grupo","Membros","Convites"};Button[] tabButtons=new Button[admin?3:2];for(int k=0;k<tabButtons.length;k++){final int position=k;Button tab=button(labels[k],k==0);tab.setTextSize(12);tab.setPadding(dp(6),dp(8),dp(6),dp(8));tabButtons[k]=tab;tabs.addView(tab,new LayoutParams(0,dp(44),1));tab.setOnClickListener(v->{for(int j=0;j<panes.length;j++)panes[j].setVisibility(j==position?VISIBLE:GONE);for(int j=0;j<tabButtons.length;j++)AppStyle.button(tabButtons[j],j==position);});}ImageView photo=avatar(group.optString("foto_path"),true);LayoutParams photoLP=new LayoutParams(dp(84),dp(84));photoLP.gravity=Gravity.CENTER_HORIZONTAL;details.addView(photo,photoLP);TextView status=text(admin?"Administrador • participantes entram por convite":"Participante",12,0xffc2aedb);sheet.footer.setVisibility(VISIBLE);sheet.footer.addView(status);EditText name=NativeSheet.input(getContext(),"Nome do grupo",60);name.setText(group.optString("nome"));name.setEnabled(admin);details.addView(name);if(admin){Button image=button("Alterar foto",false);AppStyle.icon(image,ActionIcon.IMAGE,0xffc5a1ff);details.addView(image);image.setOnClickListener(v->{if(!(getContext() instanceof MainActivity))return;((MainActivity)getContext()).chooseStickerImage(uri->{image.setEnabled(false);sheet.busy(true);repo.groupPhoto(id,uri,(r,e)->{sheet.busy(false);image.setEnabled(true);if(e!=null){status.setText(e);return;}String path=r.optJSONObject(0).optString("foto_path");try{group.put("foto_path",path);}catch(JSONException ignored){}AccountImageLoader.load(photo,photoUrl(path));renderHeader();status.setText("Foto atualizada.");});});});Button save=button("Salvar nome",true);details.addView(save);save.setOnClickListener(v->{save.setEnabled(false);repo.groupRename(id,name.getText().toString(),(r,e)->{save.setEnabled(true);if(e!=null){status.setText(e);return;}try{group.put("nome",r.optJSONObject(0).optString("nome"));}catch(JSONException ignored){}renderHeader();status.setText("Nome atualizado.");});});}participants.addView(text("👥 Participantes",17,0xffefe4ff));LinearLayout members=new LinearLayout(getContext());members.setOrientation(VERTICAL);participants.addView(members);Set<String> current=new HashSet<>();repo.groupMembers(id,(rows,e)->{if(!sheet.dialog.isShowing())return;if(e!=null){status.setText(e);return;}for(int i=0;i<rows.length();i++){JSONObject m=rows.optJSONObject(i),author=m.optJSONObject("_author");String uid=m.optString("user_id");current.add(uid);LinearLayout row=row();row.addView(avatar(author==null?"":author.optString("avatar_url"),false),new LayoutParams(dp(34),dp(34)));TextView label=text((author==null?"Participante":author.optString("nome"))+(m.optBoolean("admin")?" • Admin":""),12,0xffe5daf1);label.setPadding(dp(8),0,0,0);row.addView(label,new LayoutParams(0,-2,1));if(admin&&!me().equals(uid)&&!group.optString("criado_por").equals(uid)){Button actions=button("⋯",false);row.addView(actions,new LayoutParams(dp(42),dp(42)));actions.setOnClickListener(v->{NativeSheet menu=new NativeSheet(getContext(),"Participante");Button role=button(m.optBoolean("admin")?"Remover administrador":"Tornar administrador",false),remove=button("Remover do grupo",false);menu.body.addView(role);menu.body.addView(remove);role.setOnClickListener(w->confirm("Alterar permissão deste participante?",()->repo.groupMemberAction(id,uid,true,!m.optBoolean("admin"),(r,f)->{if(f!=null){status.setText(f);return;}menu.dialog.dismiss();sheet.dialog.dismiss();settings();})));remove.setOnClickListener(w->confirm("Remover este participante?",()->repo.groupMemberAction(id,uid,false,false,(r,f)->{if(f!=null){status.setText(f);return;}menu.dialog.dismiss();sheet.dialog.dismiss();settings();})));menu.show();});}members.addView(row);}if(admin){Button invite=button("Convidar amigos",true);invites.addView(invite);invites.addView(text("Novos participantes precisam aceitar o convite.",12,0xffb4a4c9));invite.setEnabled(false);repo.groupPending(id,(pending,f)->{if(f!=null){status.setText(f);return;}for(int j=0;j<pending.length();j++)current.add(pending.optJSONObject(j).optString("user_id"));invite.setEnabled(true);});invite.setOnClickListener(v->{NativeSheet picker=new NativeSheet(getContext(),"Convidar amigos");Set<String> chosen=new LinkedHashSet<>();TextView s=text("",12,0xffbca6da);picker.body.addView(s);LinearLayout people=new LinearLayout(getContext());people.setOrientation(VERTICAL);picker.body.addView(people);loadFriends(people,chosen,current,s,0);Button send=button("Enviar convites",true);picker.footer.setVisibility(VISIBLE);picker.footer.addView(send);send.setOnClickListener(w->{if(chosen.isEmpty()){s.setText("Escolha um amigo.");return;}send.setEnabled(false);picker.busy(true);inviteNext(new ArrayList<>(chosen),0,id,picker,s,send);});picker.show();});}});Button leave=button("Sair do grupo",false);details.addView(leave);leave.setOnClickListener(v->confirm("Sair deste grupo?",()->repo.groupLeave(id,(r,e)->{if(e!=null){status.setText(e);return;}sheet.dialog.dismiss();back();})));sheet.show();}
 private void inviteNext(List<String> ids,int index,String group,NativeSheet sheet,TextView state,Button button){if(index>=ids.size()){sheet.busy(false);sheet.dialog.dismiss();Toast.makeText(getContext(),"Convites enviados",Toast.LENGTH_SHORT).show();return;}repo.groupInvite(group,ids.get(index),(r,e)->{if(e!=null){sheet.busy(false);button.setEnabled(true);state.setText(index+" enviados. "+e);return;}inviteNext(ids,index+1,group,sheet,state,button);});}
 private void confirm(String title,Runnable action){NativeSheet s=new NativeSheet(getContext(),title);Button yes=button("Confirmar",true);s.body.addView(yes);yes.setOnClickListener(v->{s.dialog.dismiss();action.run();});s.show();}
 private ImageView avatar(String path,boolean group){ImageView image=new ImageView(getContext());image.setImageResource(R.drawable.app_logo);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(AppStyle.shape(image,0xff30253e,42));image.setClipToOutline(true);AccountImageLoader.load(image,group?photoUrl(path):path);return image;}
 private String photoUrl(String path){return path.matches("[a-zA-Z0-9-]+/[a-zA-Z0-9._-]+\\.(jpg|jpeg|png|webp)")?BuildConfig.SUPABASE_URL+"/storage/v1/object/public/group-avatars/"+path:"";}
 private String me(){return SessionPreferences.get(getContext()).getString("user_id","");}
 private LinearLayout panel(){LinearLayout p=new LinearLayout(getContext());p.setOrientation(VERTICAL);p.setPadding(dp(12),dp(10),dp(12),dp(10));p.setBackground(AppStyle.shape(p,0xdd211b2e,16));LayoutParams lp=new LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(4));p.setLayoutParams(lp);return p;}
 private LinearLayout row(){LinearLayout p=panel();p.setOrientation(HORIZONTAL);p.setGravity(Gravity.CENTER_VERTICAL);return p;}
 private Button button(String value,boolean primary){Button b=new Button(getContext());b.setText(value);b.setMinWidth(0);AppStyle.button(b,primary);return b;}
 private TextView text(String value,int size,int color){TextView t=NativeSheet.text(getContext(),value,size,color);t.setIncludeFontPadding(false);t.setPadding(0,dp(3),0,dp(3));return t;}
 private int dp(int n){return NativeSheet.dp(getContext(),n);}
}
